#!/usr/bin/env node
/**
 * Admin > Vehicle Data > "Import from Excel" and "Download Excel", redesigned (the same steps, checks and texts as before).
 *  - Import: a step bar (template, file, import); the file chosen in a drop area (click, or drag the file in); "rows that already exist" as two
 *    option cards; the check's numbers as coloured tiles; the rows in a table with a fixed header; the Import button in a navy bar.
 *  - Download: the brand list with the chosen brand's logo and how many models; a picture of the sheet's columns (EN / AR / 中文);
 *    the download in a navy bar, with what is being prepared and the file name when done.
 * Admin only (no API change). Replaces VehicleImportPanel.jsx and VehicleExportPanel.jsx (only if they are the versions this patch expects).
 *   node scripts/patch-vehicle-excel-redesign.js            dry run
 *   node scripts/patch-vehicle-excel-redesign.js --write    applies it
 */
const DATA = {"created": [], "replaced": [{"file": "apps/admin-dashboard/src/VehicleImportPanel.jsx", "what": "Vehicle Data > Import from Excel: redesigned (three steps, a drop area, option cards, number tiles, the rows table, the Import bar)", "done": "patch-vehicle-excel-redesign: the three steps", "from": ["import React, { useState } from \"react\";\nimport { Download, FileSpreadsheet, Check, AlertTriangle } from \"lucide-react\";\nimport { C, body } from \"./theme\";\nimport { SessionExpiredError, getStoredToken, previewVehicleImport, commitVehicleImport, downloadVehicleImportTemplate } from \"./auth\";\nimport { exportToExcel } from \"./exportToExcel\";\nimport UnusedPicturesCard from \"./UnusedPicturesCard\";\n\n// \"Import from Excel\" on the Vehicle Data page: choose a file in the template's layout, CHECK it (nothing is saved), read what will happen, then IMPORT (all or nothing).\nconst STATUS = {\n  new: { label: \"New\", color: \"#16794F\", bg: \"#E6F5EE\" },\n  update: { label: \"Update\", color: \"#1D4E89\", bg: \"#E5EEF9\" },\n  exists: { label: \"Already exists\", color: \"#4B5563\", bg: \"#EEF0F3\" },\n  error: { label: \"Problem\", color: \"#B42318\", bg: \"#FBE7E5\" },\n};\nconst LEVEL_COLOR = { error: \"#B42318\", warning: \"#8A5A12\", info: \"#4B5563\" };\nconst SHOWN_AT_FIRST = 100;\nconst sizeText = (bytes) => (bytes >= 1048576 ? `${(bytes / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`);\nconst plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;\n\nfunction downloadBlob(blob, filename) {\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url; link.download = filename;\n  document.body.appendChild(link); link.click(); document.body.removeChild(link);\n  URL.revokeObjectURL(url);\n}\n\nexport default function VehicleImportPanel({ onSessionExpired, onGoToBrands }) {\n  const [file, setFile] = useState(null);\n  const [mode, setMode] = useState(\"skip\");\n  const [replacePictures, setReplacePictures] = useState(true);      // \"use the pictures in this file for vehicles that already exist\" (the old pictures are removed)\n  const [phase, setPhase] = useState(\"idle\");              // idle | checking | checked | importing | done\n  const [preview, setPreview] = useState(null);\n  const [result, setResult] = useState(null);\n  const [error, setError] = useState(null);\n  const [problemsOnly, setProblemsOnly] = useState(false);\n  const [showAll, setShowAll] = useState(false);\n\n  const fail = (err) => {\n    if (err instanceof SessionExpiredError) { onSessionExpired(); return; }\n    setError(err.message);\n    if (err.payload && err.payload.rows) setPreview(err.payload);       // a refusal that explains itself: show what is wrong\n  };\n  const runCheck = async (theFile, theMode, thePictures = replacePictures) => {\n    setPhase(\"checking\"); setError(null); setResult(null); setShowAll(false);\n    try { setPreview(await previewVehicleImport(getStoredToken(), theFile, theMode, thePictures)); setPhase(\"checked\"); }\n    catch (err) { setPreview(null); setPhase(\"idle\"); fail(err); }\n  };\n  const handleTemplate = async () => {\n    setError(null);\n    try { downloadBlob(await downloadVehicleImportTemplate(getStoredToken()), \"Leap_Vehicle_Import_Template.xlsx\"); } catch (err) { fail(err); }\n  };\n  const handleMode = (next) => { setMode(next); if (file && phase === \"checked\") runCheck(file, next); };\n  const handlePictures = (next) => { setReplacePictures(next); if (file && phase === \"checked\") runCheck(file, mode, next); };\n  const handleImport = async () => {\n    setPhase(\"importing\"); setError(null);\n    try { const done = await commitVehicleImport(getStoredToken(), file, mode, replacePictures); setResult(done); setPreview(null); setPhase(\"done\"); }\n    catch (err) { setPhase(\"checked\"); fail(err); }\n  };\n  const reset = () => { setFile(null); setPreview(null); setResult(null); setError(null); setPhase(\"idle\"); setMode(\"skip\"); setReplacePictures(true); };\n  const handleReport = () => exportToExcel({\n    sheetName: \"Import check\", filename: `Vehicle_import_report_${preview.fileName.replace(/\\.xlsx$/i, \"\")}.xlsx`,\n    columns: [{ header: \"Row\", key: \"row\", width: 8 }, { header: \"Brand\", key: \"brand\", width: 16 }, { header: \"Model\", key: \"model\", width: 14 }, { header: \"Year\", key: \"year\", width: 8 }, { header: \"Version\", key: \"version\", width: 34 }, { header: \"Seats\", key: \"seats\", width: 8 }, { header: \"Picture\", key: \"picture\", width: 12 }, { header: \"Result\", key: \"result\", width: 16 }, { header: \"Messages\", key: \"messages\", width: 80 }],\n    rows: preview.rows.map((r) => ({ row: r.rowNumber, brand: r.brand, model: r.model, year: r.year, version: r.version, seats: r.seats, picture: r.picture ? `${r.picture.width}x${r.picture.height}` : \"none\", result: STATUS[r.status].label, messages: r.messages.map((m) => m.text).join(\" | \") })),\n  });\n\n  const box = { border: `1px solid ${C.line}`, borderRadius: 10, padding: 14, background: C.card, marginBottom: 14 };\n  const button = (primary, disabled) => ({ ...body, display: \"inline-flex\", alignItems: \"center\", gap: 6, padding: \"8px 14px\", borderRadius: 8, border: primary ? \"none\" : `1px solid ${C.line}`, background: disabled ? \"#D1D5DB\" : primary ? C.signal : C.card, color: primary ? C.onSignal : C.ink, fontSize: 12.5, fontWeight: 700, cursor: disabled ? \"not-allowed\" : \"pointer\" });\n  const s = preview?.summary;\n  const toImport = s ? s.newVersions + s.updatedVersions : 0;\n  const shownRows = preview ? preview.rows.filter((r) => !problemsOnly || r.status === \"error\" || r.messages.some((m) => m.level === \"warning\")) : [];\n  const visibleRows = showAll ? shownRows : shownRows.slice(0, SHOWN_AT_FIRST);\n  const tile = (value, label, warn) => (\n    <div key={label} style={{ background: warn ? \"#FDF3E1\" : C.canvas, borderRadius: 8, padding: \"8px 12px\", minWidth: 110 }}>\n      <div style={{ ...body, fontSize: 18, fontWeight: 700, color: C.ink }}>{value}</div>\n      <div style={{ ...body, fontSize: 11, color: C.muted }}>{label}</div>\n    </div>\n  );\n\n  return (\n    <div>\n      <div style={box}>\n        <div style={{ ...body, fontSize: 13, fontWeight: 700, color: C.ink, marginBottom: 4 }}>Import vehicles from an Excel sheet</div>\n        <div style={{ ...body, fontSize: 12.5, color: C.muted, marginBottom: 12 }}>\n          One row = one version of a vehicle in one year, with its names in English, Arabic and Chinese, its seats, and its picture. The brand must already exist (add it in the Brands tab, with its photo); models and years are created for you. The file is checked first and nothing is saved until you press Import.\n        </div>\n        <button onClick={handleTemplate} style={button(false, false)}><Download size={14} /> Download the template (.xlsx)</button>\n      </div>\n\n      {error && <div role=\"alert\" style={{ ...body, fontSize: 12.5, color: C.red, background: \"#FBE7E5\", borderRadius: 8, padding: 10, marginBottom: 14 }}>{error}</div>}\n\n      {phase !== \"done\" && (\n        <div style={box}>\n          <div style={{ display: \"flex\", gap: 10, alignItems: \"center\", flexWrap: \"wrap\" }}>\n            <label style={{ ...button(false, phase === \"checking\" || phase === \"importing\"), }}>\n              <FileSpreadsheet size={14} /> {file ? \"Choose another file\" : \"Choose the Excel file\"}\n              <input type=\"file\" aria-label=\"Excel file\" accept=\".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\" disabled={phase === \"checking\" || phase === \"importing\"}\n                onChange={(e) => { const f = e.target.files?.[0]; if (f) { setFile(f); setPreview(null); setError(null); setPhase(\"idle\"); } }} style={{ display: \"none\" }} />\n            </label>\n            {file && <span style={{ ...body, fontSize: 12.5, color: C.ink }}>{file.name} <span style={{ color: C.muted }}>· {sizeText(file.size)}</span></span>}\n            <button disabled={!file || phase === \"checking\" || phase === \"importing\"} onClick={() => runCheck(file, mode)} style={button(true, !file || phase === \"checking\" || phase === \"importing\")}>\n              <Check size={14} /> {phase === \"checking\" ? \"Checking…\" : \"Check file\"}\n            </button>\n          </div>\n          <div role=\"radiogroup\" aria-label=\"Rows that already exist\" style={{ ...body, fontSize: 12.5, color: C.ink, marginTop: 12, display: \"flex\", gap: 18, flexWrap: \"wrap\" }}>\n            <label style={{ display: \"flex\", gap: 6, alignItems: \"center\" }}><input type=\"radio\" name=\"import-mode\" checked={mode === \"skip\"} onChange={() => handleMode(\"skip\")} /> Skip rows that already exist (recommended)</label>\n            <label style={{ display: \"flex\", gap: 6, alignItems: \"center\" }}><input type=\"radio\" name=\"import-mode\" checked={mode === \"update\"} onChange={() => handleMode(\"update\")} /> Update rows that already exist</label>\n          </div>\n          <label style={{ ...body, fontSize: 12.5, color: C.ink, marginTop: 8, display: \"flex\", gap: 6, alignItems: \"center\" }}>\n            <input type=\"checkbox\" checked={mode === \"update\" ? true : replacePictures} disabled={mode === \"update\"} onChange={(e) => handlePictures(e.target.checked)} /> Use the pictures in this file for vehicles that already exist (the old pictures are removed){mode === \"update\" ? \" - always on when updating\" : \"\"}\n          </label>\n        </div>\n      )}\n\n      {preview && (phase === \"checked\" || phase === \"importing\") && s && (\n        <div style={box}>\n          <div style={{ display: \"flex\", gap: 8, flexWrap: \"wrap\", marginBottom: 12 }}>\n            {tile(s.rows, \"rows read\")}\n            {tile(s.newBrands || 0, \"new brands\")}\n            {(s.brandNamesUpdated || s.brandLogosSaved) ? tile((s.brandNamesUpdated || 0) + (s.brandLogosSaved || 0), \"brand updates\") : null}\n            {s.newBrandsWithoutLogo > 0 && tile(s.newBrandsWithoutLogo, 'brands saved as \"No logo yet\"', true)}\n            {tile(s.newModels, \"new models\")}\n            {tile(s.newYears, \"new years\")}\n            {tile(s.newVersions, \"new versions\")}\n            {tile(s.existingVersions, \"already exist\")}\n            {mode === \"update\" && tile(s.updatedVersions, \"to update\")}\n            {tile(s.picturesFound, \"pictures found\")}\n            {s.picturesReplaced > 0 && tile(s.picturesReplaced, \"pictures replace old ones\")}\n            {tile(s.newWithoutPicture, 'saved as \"No photo yet\"', s.newWithoutPicture > 0)}\n          </div>\n\n          {s.missingBrands.length > 0 && (\n            <div role=\"alert\" style={{ ...body, fontSize: 12.5, color: \"#B42318\", background: \"#FBE7E5\", borderRadius: 8, padding: 10, marginBottom: 8 }}>\n              {s.missingBrands.map((b) => `Brand \"${b}\"`).join(\", \")} {s.missingBrands.length === 1 ? \"does\" : \"do\"} not exist yet. Add {s.missingBrands.length === 1 ? \"it\" : \"them\"} first in the Brands tab (with the photo), then check the file again. <b>This blocks the import.</b>\n              {onGoToBrands && <button onClick={onGoToBrands} style={{ ...body, marginLeft: 8, border: \"none\", background: \"none\", color: \"#B42318\", fontWeight: 700, textDecoration: \"underline\", cursor: \"pointer\" }}>Go to Brands</button>}\n            </div>\n          )}\n          {s.rowsWithErrors > 0 && s.missingBrands.length === 0 && (\n            <div role=\"alert\" style={{ ...body, fontSize: 12.5, color: \"#B42318\", background: \"#FBE7E5\", borderRadius: 8, padding: 10, marginBottom: 8 }}>{plural(s.rowsWithErrors, \"row has a problem\", \"rows have problems\")}. Fix the file and check it again. <b>This blocks the import.</b></div>\n          )}\n          {s.newWithoutPicture > 0 && <div style={{ ...body, fontSize: 12.5, color: \"#8A5A12\", background: \"#FDF3E1\", borderRadius: 8, padding: 10, marginBottom: 8 }}>{plural(s.newWithoutPicture, \"new version has\", \"new versions have\")} no picture. {s.newWithoutPicture === 1 ? \"It\" : \"They\"} will be saved marked \"No photo yet\": add the photo later in Vehicle Data (brand, model, year, Versions).</div>}\n          {preview.nothingToImport && <div style={{ ...body, fontSize: 12.5, color: C.ink, background: C.canvas, borderRadius: 8, padding: 10, marginBottom: 8 }}>Nothing to import: every row already exists{mode === \"skip\" ? ' (choose \"Update rows that already exist\" to bring them up to date)' : \" and nothing changed\"}.</div>}\n          {preview.notes.map((n, i) => <div key={i} style={{ ...body, fontSize: 12, color: C.muted, marginBottom: 4 }}>{n}</div>)}\n          {preview.issues.map((n, i) => <div key={`i${i}`} style={{ ...body, fontSize: 12, color: LEVEL_COLOR[n.level] || C.muted, marginBottom: 4 }}>{n.text}</div>)}\n\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, margin: \"12px 0 8px\", flexWrap: \"wrap\" }}>\n            <label style={{ ...body, fontSize: 12.5, color: C.ink, display: \"flex\", gap: 6, alignItems: \"center\" }}><input type=\"checkbox\" checked={problemsOnly} onChange={(e) => { setProblemsOnly(e.target.checked); setShowAll(false); }} /> Problems and warnings only</label>\n            <span style={{ ...body, fontSize: 12, color: C.muted }}>{shownRows.length} of {preview.rows.length} rows</span>\n            <button onClick={handleReport} style={{ ...button(false, false), marginLeft: \"auto\" }}><Download size={14} /> Download report (.xlsx)</button>\n          </div>\n          <div style={{ overflowX: \"auto\" }}>\n            <table style={{ width: \"100%\", borderCollapse: \"collapse\", ...body, fontSize: 12 }}>\n              <thead><tr>{[\"Row\", \"Model\", \"Year\", \"Version\", \"Seats\", \"Picture\", \"Result\"].map((h) => <th key={h} style={{ textAlign: \"left\", padding: \"6px 8px\", borderBottom: `1px solid ${C.line}`, color: C.muted, fontWeight: 700 }}>{h}</th>)}</tr></thead>\n              <tbody>\n                {visibleRows.map((r) => (\n                  <tr key={r.rowNumber} data-status={r.status}>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>{r.rowNumber}</td>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>{r.model}</td>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>{r.year}</td>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>{r.version}</td>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>{r.seats}</td>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>{r.picture ? `${r.picture.width}×${r.picture.height}` : \"none\"}</td>\n                    <td style={{ padding: \"6px 8px\", borderBottom: `1px solid ${C.line}` }}>\n                      <span style={{ fontSize: 11, fontWeight: 700, color: STATUS[r.status].color, background: STATUS[r.status].bg, borderRadius: 999, padding: \"2px 8px\" }}>{STATUS[r.status].label}</span>\n                      {r.messages.map((m, i) => <div key={i} style={{ fontSize: 11.5, color: LEVEL_COLOR[m.level], marginTop: 2 }}>{m.text}</div>)}\n                    </td>\n                  </tr>\n                ))}\n              </tbody>\n            </table>\n          </div>\n          {!showAll && shownRows.length > SHOWN_AT_FIRST && <button onClick={() => setShowAll(true)} style={{ ...button(false, false), marginTop: 8 }}>Show all {shownRows.length} rows</button>}\n\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, marginTop: 14 }}>\n            <button disabled={!preview.ready || phase === \"importing\"} onClick={handleImport} style={button(true, !preview.ready || phase === \"importing\")}>\n              {phase === \"importing\" ? \"Importing…\" : `Import ${plural(toImport, \"vehicle\", \"vehicles\")}`}\n            </button>\n            <span style={{ ...body, fontSize: 12, color: C.muted }}>Nothing is saved until you press Import. Everything is saved together, or nothing.</span>\n          </div>\n        </div>\n      )}\n\n      {phase === \"done\" && result && (\n        <div style={{ ...box, borderColor: \"#16794F\" }}>\n          <div style={{ ...body, fontSize: 14, fontWeight: 700, color: \"#16794F\", display: \"flex\", alignItems: \"center\", gap: 6, marginBottom: 6 }}><Check size={16} /> Import finished</div>\n          <div style={{ ...body, fontSize: 12.5, color: C.ink, lineHeight: 1.6 }}>\n            {result.summary.newBrands > 0 ? `${plural(result.summary.newBrands, \"brand\", \"brands\")} created; ` : \"\"}{plural(result.summary.newVersions, \"version\", \"versions\")} added{result.summary.updatedVersions > 0 ? `, ${plural(result.summary.updatedVersions, \"version\", \"versions\")} updated` : \"\"}; {plural(result.summary.newModels, \"model\", \"models\")} and {plural(result.summary.newYears, \"year\", \"years\")} created; {plural(result.summary.picturesToSave, \"picture\", \"pictures\")} saved; {plural(result.summary.existingVersions, \"row\", \"rows\")} already existed.\n            {result.summary.newWithoutPicture > 0 && <div style={{ color: \"#8A5A12\", display: \"flex\", gap: 6, alignItems: \"center\", marginTop: 6 }}><AlertTriangle size={14} /> {plural(result.summary.newWithoutPicture, \"version is\", \"versions are\")} marked \"No photo yet\" (and the new years have no photo): add them in Vehicle Data (brand, model, year, Versions).</div>}\n          </div>\n          {result.oldPicturesRemoved > 0 && <div style={{ ...body, fontSize: 12.5, color: C.ink, marginTop: 6 }}>{plural(result.oldPicturesRemoved, \"old picture was\", \"old pictures were\")} removed from the server.</div>}\n          <button onClick={reset} style={{ ...button(false, false), marginTop: 12 }}>Check another file</button>\n        </div>\n      )}\n      <UnusedPicturesCard onSessionExpired={onSessionExpired} />\n    </div>\n  );\n}\n"], "text": "import React, { useState } from \"react\";\nimport { Download, FileSpreadsheet, Check, AlertTriangle, Upload } from \"lucide-react\";\nimport { C, body, disp, mono } from \"./theme\";\nimport { SessionExpiredError, getStoredToken, previewVehicleImport, commitVehicleImport, downloadVehicleImportTemplate } from \"./auth\";\nimport { exportToExcel } from \"./exportToExcel\";\nimport UnusedPicturesCard from \"./UnusedPicturesCard\";\n\n// \"Import from Excel\" on the Vehicle Data page: choose a file in the template's layout, CHECK it (nothing is saved), read what will happen, then IMPORT (all or nothing).\n// patch-vehicle-excel-redesign: the three steps (template, file, import) as a step bar; the file is chosen in a drop area (drag the file in, or click);\n// \"rows that already exist\" as two option cards; the check's numbers as tiles; the rows in a table with a fixed header; the Import button in a bar under it.\nconst STATUS = {\n  new: { label: \"New\", color: \"#16794F\", bg: \"#E6F5EE\" },\n  update: { label: \"Update\", color: \"#1D4E89\", bg: \"#E5EEF9\" },\n  exists: { label: \"Already exists\", color: \"#4B5563\", bg: \"#EEF0F3\" },\n  error: { label: \"Problem\", color: \"#B42318\", bg: \"#FBE7E5\" },\n};\nconst LEVEL_COLOR = { error: \"#B42318\", warning: \"#8A5A12\", info: \"#4B5563\" };\nconst SHOWN_AT_FIRST = 100;\nconst sizeText = (bytes) => (bytes >= 1048576 ? `${(bytes / 1048576).toFixed(1)} MB` : `${Math.max(1, Math.round(bytes / 1024))} KB`);\nconst plural = (n, one, many) => `${n} ${n === 1 ? one : many}`;\n\nfunction downloadBlob(blob, filename) {\n  const url = URL.createObjectURL(blob);\n  const link = document.createElement(\"a\");\n  link.href = url; link.download = filename;\n  document.body.appendChild(link); link.click(); document.body.removeChild(link);\n  URL.revokeObjectURL(url);\n}\n\nexport default function VehicleImportPanel({ onSessionExpired, onGoToBrands }) {\n  const [file, setFile] = useState(null);\n  const [mode, setMode] = useState(\"skip\");\n  const [replacePictures, setReplacePictures] = useState(true);      // \"use the pictures in this file for vehicles that already exist\" (the old pictures are removed)\n  const [phase, setPhase] = useState(\"idle\");              // idle | checking | checked | importing | done\n  const [preview, setPreview] = useState(null);\n  const [result, setResult] = useState(null);\n  const [error, setError] = useState(null);\n  const [problemsOnly, setProblemsOnly] = useState(false);\n  const [showAll, setShowAll] = useState(false);\n  const [dragOver, setDragOver] = useState(false);\n  const [templateDone, setTemplateDone] = useState(false);\n\n  const fail = (err) => {\n    if (err instanceof SessionExpiredError) { onSessionExpired(); return; }\n    setError(err.message);\n    if (err.payload && err.payload.rows) setPreview(err.payload);       // a refusal that explains itself: show what is wrong\n  };\n  const runCheck = async (theFile, theMode, thePictures = replacePictures) => {\n    setPhase(\"checking\"); setError(null); setResult(null); setShowAll(false);\n    try { setPreview(await previewVehicleImport(getStoredToken(), theFile, theMode, thePictures)); setPhase(\"checked\"); }\n    catch (err) { setPreview(null); setPhase(\"idle\"); fail(err); }\n  };\n  const handleTemplate = async () => {\n    setError(null);\n    try { downloadBlob(await downloadVehicleImportTemplate(getStoredToken()), \"Leap_Vehicle_Import_Template.xlsx\"); setTemplateDone(true); } catch (err) { fail(err); }\n  };\n  const handleMode = (next) => { setMode(next); if (file && phase === \"checked\") runCheck(file, next); };\n  const handlePictures = (next) => { setReplacePictures(next); if (file && phase === \"checked\") runCheck(file, mode, next); };\n  const handleImport = async () => {\n    setPhase(\"importing\"); setError(null);\n    try { const done = await commitVehicleImport(getStoredToken(), file, mode, replacePictures); setResult(done); setPreview(null); setPhase(\"done\"); }\n    catch (err) { setPhase(\"checked\"); fail(err); }\n  };\n  const reset = () => { setFile(null); setPreview(null); setResult(null); setError(null); setPhase(\"idle\"); setMode(\"skip\"); setReplacePictures(true); };\n  const pickFile = (f) => { if (f) { setFile(f); setPreview(null); setError(null); setPhase(\"idle\"); } };\n  const handleReport = () => exportToExcel({\n    sheetName: \"Import check\", filename: `Vehicle_import_report_${preview.fileName.replace(/\\.xlsx$/i, \"\")}.xlsx`,\n    columns: [{ header: \"Row\", key: \"row\", width: 8 }, { header: \"Brand\", key: \"brand\", width: 16 }, { header: \"Model\", key: \"model\", width: 14 }, { header: \"Year\", key: \"year\", width: 8 }, { header: \"Version\", key: \"version\", width: 34 }, { header: \"Seats\", key: \"seats\", width: 8 }, { header: \"Picture\", key: \"picture\", width: 12 }, { header: \"Result\", key: \"result\", width: 16 }, { header: \"Messages\", key: \"messages\", width: 80 }],\n    rows: preview.rows.map((r) => ({ row: r.rowNumber, brand: r.brand, model: r.model, year: r.year, version: r.version, seats: r.seats, picture: r.picture ? `${r.picture.width}x${r.picture.height}` : \"none\", result: STATUS[r.status].label, messages: r.messages.map((m) => m.text).join(\" | \") })),\n  });\n\n  const busy = phase === \"checking\" || phase === \"importing\";\n  const card = { border: `1px solid ${C.line}`, borderRadius: 14, padding: 18, background: \"#fff\", boxShadow: \"0 1px 2px rgba(11,49,70,0.05)\", marginBottom: 16 };\n  const button = (primary, disabled) => ({ ...body, display: \"inline-flex\", alignItems: \"center\", gap: 7, height: 40, boxSizing: \"border-box\", padding: \"0 16px\", borderRadius: 10, border: primary ? `1px solid ${disabled ? \"#D1D5DB\" : C.signalDark}` : `1px solid ${C.line}`, background: disabled ? \"#D1D5DB\" : primary ? C.signal : \"#fff\", color: primary ? C.onSignal : C.ink, fontSize: 13, fontWeight: 800, cursor: disabled ? \"not-allowed\" : \"pointer\", whiteSpace: \"nowrap\" });\n  const note = (bg, color) => ({ ...body, fontSize: 12.5, color, background: bg, borderRadius: 10, padding: \"10px 12px\", marginBottom: 8, lineHeight: 1.5 });\n  const s = preview?.summary;\n  const toImport = s ? s.newVersions + s.updatedVersions : 0;\n  const shownRows = preview ? preview.rows.filter((r) => !problemsOnly || r.status === \"error\" || r.messages.some((m) => m.level === \"warning\")) : [];\n  const visibleRows = showAll ? shownRows : shownRows.slice(0, SHOWN_AT_FIRST);\n  // a number tile: green for what will be added, grey for what already exists, amber for what needs a look later\n  const tile = (value, label, tone = \"plain\") => {\n    const t = { plain: [C.surfaceHigh, C.ink, C.line], add: [\"#EEF8F3\", C.gaugeInk, \"#CDEBDD\"], warn: [C.amberBg, C.amberInk, \"#F1D9A8\"], info: [\"#EEF3FC\", C.torqueInk, \"#D3E0F7\"] }[tone];\n    return (\n      <div key={label} style={{ background: t[0], border: `1px solid ${t[2]}`, borderRadius: 12, padding: \"10px 12px\" }}>\n        <div style={{ ...mono, fontSize: 20, fontWeight: 800, color: t[1] }}>{value}</div>\n        <div style={{ ...body, fontSize: 11.5, fontWeight: 600, color: C.muted }}>{label}</div>\n      </div>\n    );\n  };\n  const stepNow = phase === \"done\" ? 3 : phase === \"checked\" || phase === \"importing\" ? 2 : file ? 1 : templateDone ? 1 : 0;\n  const steps = [[\"Get the template\", \"the columns the file must have\"], [\"Choose and check the file\", \"nothing is saved yet\"], [\"Import\", \"everything together, or nothing\"]];\n  const optionCard = (value, title, text) => (\n    <label key={value} style={{ ...body, flex: \"1 1 240px\", display: \"flex\", gap: 10, alignItems: \"flex-start\", padding: \"11px 13px\", borderRadius: 12, cursor: busy ? \"default\" : \"pointer\",\n      border: `1.5px solid ${mode === value ? C.signal : C.line}`, background: mode === value ? C.goldTint : \"#fff\" }}>\n      <input type=\"radio\" name=\"import-mode\" checked={mode === value} onChange={() => handleMode(value)} disabled={busy} style={{ marginTop: 2, accentColor: C.navy }} />\n      <span>\n        <span style={{ display: \"block\", fontSize: 13, fontWeight: 800, color: C.ink }}>{title}</span>\n        <span style={{ display: \"block\", fontSize: 11.5, color: C.muted, marginTop: 2 }}>{text}</span>\n      </span>\n    </label>\n  );\n\n  return (\n    <div data-testid=\"vehicle-import\">\n      {/* the three steps */}\n      <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(3, minmax(0, 1fr))\", background: \"#fff\", border: `1px solid ${C.line}`, borderRadius: 14, overflow: \"hidden\", marginBottom: 16, boxShadow: \"0 1px 2px rgba(11,49,70,0.05)\" }}>\n        {steps.map(([title, sub], i) => {\n          const state = i < stepNow ? \"done\" : i === stepNow ? \"now\" : \"next\";\n          return (\n            <div key={title} style={{ display: \"flex\", alignItems: \"center\", gap: 10, padding: \"12px 14px\", borderLeft: i ? `1px solid ${C.line}` : \"none\", background: state === \"now\" ? C.goldTint : \"#fff\", boxShadow: state === \"now\" ? `inset 0 -3px 0 ${C.signal}` : \"none\" }}>\n              <span style={{ ...body, width: 28, height: 28, borderRadius: \"50%\", flexShrink: 0, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", fontSize: 12.5, fontWeight: 800,\n                background: state === \"done\" ? C.navy : state === \"now\" ? C.signal : C.canvas, color: state === \"done\" ? \"#fff\" : state === \"now\" ? C.onSignal : C.muted, border: state === \"next\" ? `1px solid ${C.lineStrong}` : \"none\" }}>\n                {state === \"done\" ? <Check size={14} /> : i + 1}\n              </span>\n              <span style={{ ...body, minWidth: 0 }}>\n                <span style={{ display: \"block\", fontSize: 13, fontWeight: 800, color: state === \"next\" ? C.muted : C.ink }}>{title}</span>\n                <span style={{ display: \"block\", fontSize: 11.5, color: C.muted }}>{sub}</span>\n              </span>\n            </div>\n          );\n        })}\n      </div>\n\n      {/* step 1: what the file is, and the template */}\n      <div style={{ ...card, display: \"flex\", gap: 16, alignItems: \"center\", flexWrap: \"wrap\" }}>\n        <div style={{ width: 46, height: 46, borderRadius: 12, background: \"#E7F4EC\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}><FileSpreadsheet size={22} color=\"#1D6F42\" /></div>\n        <div style={{ flex: \"1 1 380px\", minWidth: 0 }}>\n          <div style={{ ...disp, fontSize: 15.5, fontWeight: 800, color: C.ink }}>Import vehicles from an Excel sheet</div>\n          <div style={{ ...body, fontSize: 12.5, color: C.muted, marginTop: 3, lineHeight: 1.5 }}>\n            One row = one version of a vehicle in one year, with its names in English, Arabic and Chinese, its seats, and its picture. The brand must already exist (add it in the Brands tab, with its photo); models and years are created for you. The file is checked first and nothing is saved until you press Import.\n          </div>\n        </div>\n        <button onClick={handleTemplate} style={button(false, false)}><Download size={15} /> Download the template (.xlsx)</button>\n      </div>\n\n      {error && <div role=\"alert\" style={{ ...note(C.redBg, C.redInk), marginBottom: 16, display: \"flex\", gap: 8, alignItems: \"flex-start\" }}><AlertTriangle size={15} style={{ flexShrink: 0, marginTop: 1 }} /> {error}</div>}\n\n      {/* step 2: the file and the options */}\n      {phase !== \"done\" && (\n        <div style={card}>\n          <div style={{ ...disp, fontSize: 14.5, fontWeight: 800, color: C.ink, marginBottom: 10 }}>Choose the file</div>\n          <label\n            onDragOver={(e) => { e.preventDefault(); if (!busy) setDragOver(true); }}\n            onDragLeave={() => setDragOver(false)}\n            onDrop={(e) => { e.preventDefault(); setDragOver(false); if (!busy) pickFile(e.dataTransfer.files?.[0]); }}\n            style={{ ...body, display: \"flex\", alignItems: \"center\", gap: 14, padding: file ? \"14px 16px\" : \"26px 16px\", justifyContent: file ? \"flex-start\" : \"center\", flexDirection: file ? \"row\" : \"column\", textAlign: \"center\",\n              border: `2px dashed ${dragOver ? C.signal : file ? \"#9FD2B8\" : C.lineStrong}`, borderRadius: 14, background: dragOver ? C.goldTint : file ? \"#F3FAF6\" : C.surfaceHigh, cursor: busy ? \"default\" : \"pointer\" }}>\n            {file ? (\n              <>\n                <div style={{ width: 40, height: 40, borderRadius: 10, background: \"#E7F4EC\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}><FileSpreadsheet size={20} color=\"#1D6F42\" /></div>\n                <span style={{ textAlign: \"left\", minWidth: 0, flex: 1 }}>\n                  <span style={{ display: \"block\", fontSize: 13.5, fontWeight: 800, color: C.ink, overflow: \"hidden\", textOverflow: \"ellipsis\", whiteSpace: \"nowrap\" }}>{file.name} <span style={{ color: C.muted, fontWeight: 600 }}>· {sizeText(file.size)}</span></span>\n                  <span style={{ display: \"block\", fontSize: 11.5, color: C.muted }}>{phase === \"checked\" ? \"Checked. Change an option below and it is checked again.\" : \"Press Check file to read it (nothing is saved).\"}</span>\n                </span>\n                <span style={{ fontSize: 12.5, fontWeight: 700, color: C.torque, flexShrink: 0 }}>Choose another file</span>\n              </>\n            ) : (\n              <>\n                <div style={{ width: 46, height: 46, borderRadius: \"50%\", background: \"#fff\", border: `1px solid ${C.line}`, display: \"flex\", alignItems: \"center\", justifyContent: \"center\" }}><Upload size={20} color={C.navy} /></div>\n                <span style={{ fontSize: 13.5, fontWeight: 800, color: C.ink }}>Choose the Excel file</span>\n                <span style={{ fontSize: 12, color: C.muted }}>or drag it here · .xlsx in the template's layout</span>\n              </>\n            )}\n            <input type=\"file\" aria-label=\"Excel file\" accept=\".xlsx,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet\" disabled={busy}\n              onChange={(e) => pickFile(e.target.files?.[0])} style={{ display: \"none\" }} />\n          </label>\n\n          <div style={{ ...body, fontSize: 11.5, fontWeight: 800, color: C.muted, letterSpacing: \"0.06em\", textTransform: \"uppercase\", margin: \"16px 0 8px\" }}>Rows that already exist</div>\n          <div role=\"radiogroup\" aria-label=\"Rows that already exist\" style={{ display: \"flex\", gap: 10, flexWrap: \"wrap\" }}>\n            {optionCard(\"skip\", \"Skip rows that already exist (recommended)\", \"Only the new versions are added; what is already there is left as it is.\")}\n            {optionCard(\"update\", \"Update rows that already exist\", \"The names, engine and seats of versions already there are replaced with the file's.\")}\n          </div>\n          <label style={{ ...body, fontSize: 12.5, color: C.ink, marginTop: 12, display: \"flex\", gap: 8, alignItems: \"center\", padding: \"9px 12px\", borderRadius: 10, background: C.surfaceHigh, border: `1px solid ${C.line}`, opacity: mode === \"update\" ? 0.75 : 1 }}>\n            <input type=\"checkbox\" checked={mode === \"update\" ? true : replacePictures} disabled={mode === \"update\"} onChange={(e) => handlePictures(e.target.checked)} style={{ accentColor: C.navy }} /> Use the pictures in this file for vehicles that already exist (the old pictures are removed){mode === \"update\" ? \" - always on when updating\" : \"\"}\n          </label>\n\n          <div style={{ display: \"flex\", justifyContent: \"flex-end\", marginTop: 14 }}>\n            <button disabled={!file || busy} onClick={() => runCheck(file, mode)} style={button(true, !file || busy)}>\n              <Check size={15} /> {phase === \"checking\" ? \"Checking…\" : \"Check file\"}\n            </button>\n          </div>\n        </div>\n      )}\n\n      {/* step 3: what the check found, and Import */}\n      {preview && (phase === \"checked\" || phase === \"importing\") && s && (\n        <div style={{ ...card, padding: 0, overflow: \"hidden\" }}>\n          <div style={{ padding: 18 }}>\n            <div style={{ ...disp, fontSize: 14.5, fontWeight: 800, color: C.ink, marginBottom: 12 }}>What the check found</div>\n            <div style={{ display: \"grid\", gridTemplateColumns: \"repeat(auto-fill, minmax(130px, 1fr))\", gap: 10, marginBottom: 14 }}>\n              {tile(s.rows, \"rows read\")}\n              {tile(s.newBrands || 0, \"new brands\", (s.newBrands || 0) > 0 ? \"add\" : \"plain\")}\n              {(s.brandNamesUpdated || s.brandLogosSaved) ? tile((s.brandNamesUpdated || 0) + (s.brandLogosSaved || 0), \"brand updates\", \"info\") : null}\n              {s.newBrandsWithoutLogo > 0 && tile(s.newBrandsWithoutLogo, 'brands saved as \"No logo yet\"', \"warn\")}\n              {tile(s.newModels, \"new models\", s.newModels > 0 ? \"add\" : \"plain\")}\n              {tile(s.newYears, \"new years\", s.newYears > 0 ? \"add\" : \"plain\")}\n              {tile(s.newVersions, \"new versions\", s.newVersions > 0 ? \"add\" : \"plain\")}\n              {tile(s.existingVersions, \"already exist\")}\n              {mode === \"update\" && tile(s.updatedVersions, \"to update\", \"info\")}\n              {tile(s.picturesFound, \"pictures found\")}\n              {s.picturesReplaced > 0 && tile(s.picturesReplaced, \"pictures replace old ones\", \"info\")}\n              {tile(s.newWithoutPicture, 'saved as \"No photo yet\"', s.newWithoutPicture > 0 ? \"warn\" : \"plain\")}\n            </div>\n\n            {s.missingBrands.length > 0 && (\n              <div role=\"alert\" style={note(C.redBg, \"#B42318\")}>\n                {s.missingBrands.map((b) => `Brand \"${b}\"`).join(\", \")} {s.missingBrands.length === 1 ? \"does\" : \"do\"} not exist yet. Add {s.missingBrands.length === 1 ? \"it\" : \"them\"} first in the Brands tab (with the photo), then check the file again. <b>This blocks the import.</b>\n                {onGoToBrands && <button onClick={onGoToBrands} style={{ ...body, marginLeft: 8, border: \"none\", background: \"none\", color: \"#B42318\", fontWeight: 700, textDecoration: \"underline\", cursor: \"pointer\" }}>Go to Brands</button>}\n              </div>\n            )}\n            {s.rowsWithErrors > 0 && s.missingBrands.length === 0 && (\n              <div role=\"alert\" style={note(C.redBg, \"#B42318\")}>{plural(s.rowsWithErrors, \"row has a problem\", \"rows have problems\")}. Fix the file and check it again. <b>This blocks the import.</b></div>\n            )}\n            {s.newWithoutPicture > 0 && <div style={note(C.amberBg, \"#8A5A12\")}>{plural(s.newWithoutPicture, \"new version has\", \"new versions have\")} no picture. {s.newWithoutPicture === 1 ? \"It\" : \"They\"} will be saved marked \"No photo yet\": add the photo later in Vehicle Data (brand, model, year, Versions).</div>}\n            {preview.nothingToImport && <div style={note(C.surfaceHigh, C.ink)}>Nothing to import: every row already exists{mode === \"skip\" ? ' (choose \"Update rows that already exist\" to bring them up to date)' : \" and nothing changed\"}.</div>}\n            {preview.notes.map((n, i) => <div key={i} style={{ ...body, fontSize: 12, color: C.muted, marginBottom: 4 }}>{n}</div>)}\n            {preview.issues.map((n, i) => <div key={`i${i}`} style={{ ...body, fontSize: 12, color: LEVEL_COLOR[n.level] || C.muted, marginBottom: 4 }}>{n.text}</div>)}\n\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, margin: \"14px 0 10px\", flexWrap: \"wrap\" }}>\n              <label style={{ ...body, fontSize: 12.5, fontWeight: 700, color: C.ink, display: \"flex\", gap: 6, alignItems: \"center\" }}><input type=\"checkbox\" checked={problemsOnly} onChange={(e) => { setProblemsOnly(e.target.checked); setShowAll(false); }} style={{ accentColor: C.navy }} /> Problems and warnings only</label>\n              <span style={{ ...body, fontSize: 12, color: C.muted }}>{shownRows.length} of {preview.rows.length} rows</span>\n              <button onClick={handleReport} style={{ ...button(false, false), height: 34, marginLeft: \"auto\" }}><Download size={14} /> Download report (.xlsx)</button>\n            </div>\n            <div style={{ maxHeight: 460, overflow: \"auto\", border: `1px solid ${C.line}`, borderRadius: 12 }}>\n              <table style={{ width: \"100%\", borderCollapse: \"separate\", borderSpacing: 0, ...body, fontSize: 12.5 }}>\n                <thead><tr>{[\"Row\", \"Model\", \"Year\", \"Version\", \"Seats\", \"Picture\", \"Result\"].map((h) => <th key={h} style={{ position: \"sticky\", top: 0, zIndex: 1, textAlign: \"left\", padding: \"9px 10px\", background: C.surfaceHigh, borderBottom: `1px solid ${C.line}`, color: C.muted, fontSize: 11, fontWeight: 800, letterSpacing: \"0.05em\", textTransform: \"uppercase\" }}>{h}</th>)}</tr></thead>\n                <tbody>\n                  {visibleRows.map((r) => (\n                    <tr key={r.rowNumber} data-status={r.status} style={{ background: r.status === \"error\" ? \"#FFF7F6\" : \"#fff\" }}>\n                      <td style={{ ...mono, padding: \"8px 10px\", borderBottom: `1px solid ${C.line}`, color: C.muted }}>{r.rowNumber}</td>\n                      <td style={{ padding: \"8px 10px\", borderBottom: `1px solid ${C.line}`, fontWeight: 700 }}>{r.model}</td>\n                      <td style={{ ...mono, padding: \"8px 10px\", borderBottom: `1px solid ${C.line}` }}>{r.year}</td>\n                      <td style={{ padding: \"8px 10px\", borderBottom: `1px solid ${C.line}` }}>{r.version}</td>\n                      <td style={{ ...mono, padding: \"8px 10px\", borderBottom: `1px solid ${C.line}` }}>{r.seats}</td>\n                      <td style={{ ...mono, padding: \"8px 10px\", borderBottom: `1px solid ${C.line}`, color: r.picture ? C.ink : C.amberInk }}>{r.picture ? `${r.picture.width}×${r.picture.height}` : \"none\"}</td>\n                      <td style={{ padding: \"8px 10px\", borderBottom: `1px solid ${C.line}` }}>\n                        <span style={{ fontSize: 11, fontWeight: 800, color: STATUS[r.status].color, background: STATUS[r.status].bg, borderRadius: 999, padding: \"2px 9px\" }}>{STATUS[r.status].label}</span>\n                        {r.messages.map((m, i) => <div key={i} style={{ fontSize: 11.5, color: LEVEL_COLOR[m.level], marginTop: 3 }}>{m.text}</div>)}\n                      </td>\n                    </tr>\n                  ))}\n                </tbody>\n              </table>\n            </div>\n            {!showAll && shownRows.length > SHOWN_AT_FIRST && <button onClick={() => setShowAll(true)} style={{ ...button(false, false), height: 34, marginTop: 10 }}>Show all {shownRows.length} rows</button>}\n          </div>\n\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 14, padding: \"14px 18px\", background: `linear-gradient(120deg, ${C.navyDeep}, ${C.navy} 60%, ${C.navySoft} 140%)`, flexWrap: \"wrap\" }}>\n            <span style={{ ...body, fontSize: 12.5, color: C.onNavyMuted, flex: \"1 1 260px\" }}>Nothing is saved until you press Import. Everything is saved together, or nothing.</span>\n            <button disabled={!preview.ready || phase === \"importing\"} onClick={handleImport} style={{ ...button(true, !preview.ready || phase === \"importing\"), height: 42, padding: \"0 22px\", fontSize: 14 }}>\n              {phase === \"importing\" ? \"Importing…\" : `Import ${plural(toImport, \"vehicle\", \"vehicles\")}`}\n            </button>\n          </div>\n        </div>\n      )}\n\n      {phase === \"done\" && result && (\n        <div style={{ ...card, border: \"1px solid #9FD2B8\", background: \"#F3FAF6\" }}>\n          <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, marginBottom: 10 }}>\n            <span style={{ width: 40, height: 40, borderRadius: \"50%\", background: C.gauge, display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}><Check size={20} color=\"#fff\" /></span>\n            <div style={{ ...disp, fontSize: 16, fontWeight: 800, color: \"#16794F\" }}>Import finished</div>\n          </div>\n          <div style={{ ...body, fontSize: 13, color: C.ink, lineHeight: 1.6 }}>\n            {result.summary.newBrands > 0 ? `${plural(result.summary.newBrands, \"brand\", \"brands\")} created; ` : \"\"}{plural(result.summary.newVersions, \"version\", \"versions\")} added{result.summary.updatedVersions > 0 ? `, ${plural(result.summary.updatedVersions, \"version\", \"versions\")} updated` : \"\"}; {plural(result.summary.newModels, \"model\", \"models\")} and {plural(result.summary.newYears, \"year\", \"years\")} created; {plural(result.summary.picturesToSave, \"picture\", \"pictures\")} saved; {plural(result.summary.existingVersions, \"row\", \"rows\")} already existed.\n            {result.summary.newWithoutPicture > 0 && <div style={{ color: \"#8A5A12\", display: \"flex\", gap: 6, alignItems: \"center\", marginTop: 6 }}><AlertTriangle size={14} /> {plural(result.summary.newWithoutPicture, \"version is\", \"versions are\")} marked \"No photo yet\" (and the new years have no photo): add them in Vehicle Data (brand, model, year, Versions).</div>}\n          </div>\n          {result.oldPicturesRemoved > 0 && <div style={{ ...body, fontSize: 12.5, color: C.ink, marginTop: 6 }}>{plural(result.oldPicturesRemoved, \"old picture was\", \"old pictures were\")} removed from the server.</div>}\n          <button onClick={reset} style={{ ...button(false, false), marginTop: 14 }}>Check another file</button>\n        </div>\n      )}\n      <UnusedPicturesCard onSessionExpired={onSessionExpired} />\n    </div>\n  );\n}\n"}, {"file": "apps/admin-dashboard/src/VehicleExportPanel.jsx", "what": "Vehicle Data > Download Excel: redesigned (the brand with its logo and counts, the sheet's columns, the download bar)", "done": "patch-vehicle-excel-redesign: the brand chosen", "from": ["import React, { useEffect, useState } from \"react\";\nimport { Download } from \"lucide-react\";\nimport { C, body } from \"./theme\";\nimport { SessionExpiredError, getStoredToken, fetchBrands, downloadVehicleExport } from \"./auth\";\n\n// \"Download Excel\" on the Vehicle Data page: every version of one brand (or of all brands) in one sheet, the English, Arabic and Chinese\n// columns side by side and the vehicle photo in its cell -- the same layout as the import sheet.\nexport default function VehicleExportPanel({ onSessionExpired }) {\n  const [brands, setBrands] = useState([]);\n  const [brandId, setBrandId] = useState(\"\");          // \"\" = all brands\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState(null);\n  const [done, setDone] = useState(null);\n\n  useEffect(() => {\n    fetchBrands().then(setBrands).catch((err) => setError(err.message));\n  }, []);\n\n  const handleDownload = async () => {\n    setBusy(true); setError(null); setDone(null);\n    try {\n      const { blob, fileName } = await downloadVehicleExport(getStoredToken(), brandId || null);\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement(\"a\");\n      link.href = url; link.download = fileName;\n      document.body.appendChild(link); link.click(); document.body.removeChild(link);\n      URL.revokeObjectURL(url);\n      setDone(fileName);\n    } catch (err) {\n      if (err instanceof SessionExpiredError) { onSessionExpired(); return; }\n      setError(err.message);\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const box = { border: `1px solid ${C.line}`, borderRadius: 10, padding: 14, background: C.card, marginBottom: 14 };\n  const button = { ...body, display: \"inline-flex\", alignItems: \"center\", gap: 6, padding: \"8px 14px\", borderRadius: 8, border: \"none\", background: busy ? \"#D1D5DB\" : C.signal, color: C.onSignal, fontSize: 12.5, fontWeight: 700, cursor: busy ? \"not-allowed\" : \"pointer\" };\n  return (\n    <div style={box}>\n      <div style={{ ...body, fontSize: 13, fontWeight: 700, color: C.ink, marginBottom: 4 }}>Download the vehicle data as an Excel sheet</div>\n      <div style={{ ...body, fontSize: 12.5, color: C.muted, marginBottom: 12 }}>\n        One row = one version of a vehicle in one year: brand, model, year, version, engine and seats in English, Arabic and Chinese, and the vehicle photo in its cell (click it to open it full size). All brands can take a minute because of the photos.\n      </div>\n      <div style={{ display: \"flex\", gap: 10, alignItems: \"center\", flexWrap: \"wrap\" }}>\n        <label htmlFor=\"vehicle-export-brand\" style={{ ...body, fontSize: 12.5, color: C.ink, fontWeight: 600 }}>Brand</label>\n        <select id=\"vehicle-export-brand\" value={brandId} onChange={(e) => setBrandId(e.target.value)} disabled={busy}\n          style={{ ...body, fontSize: 12.5, padding: \"7px 10px\", borderRadius: 8, border: `1px solid ${C.line}`, background: C.card, color: C.ink, minWidth: 200 }}>\n          <option value=\"\">All brands</option>\n          {brands.map((b) => <option key={b.id} value={b.id}>{b.name}{b.nameAr ? ` / ${b.nameAr}` : \"\"}</option>)}\n        </select>\n        <button onClick={handleDownload} disabled={busy} style={button}>\n          <Download size={14} /> {busy ? \"Preparing the file…\" : \"Download Excel (.xlsx)\"}\n        </button>\n      </div>\n      {error && <div role=\"alert\" style={{ ...body, fontSize: 12.5, color: C.red, background: \"#FBE7E5\", borderRadius: 8, padding: 10, marginTop: 12 }}>{error}</div>}\n      {done && <div style={{ ...body, fontSize: 12.5, color: \"#16794F\", marginTop: 12 }}>Downloaded {done}</div>}\n    </div>\n  );\n}\n"], "text": "import React, { useEffect, useState } from \"react\";\nimport { Download, FileSpreadsheet, Check, AlertTriangle, ImagePlus } from \"lucide-react\";\nimport { C, body, disp, mono } from \"./theme\";\nimport { API_BASE_URL, SessionExpiredError, getStoredToken, fetchBrands, downloadVehicleExport } from \"./auth\";\n\n// \"Download Excel\" on the Vehicle Data page: every version of one brand (or of all brands) in one sheet, the English, Arabic and Chinese\n// columns side by side and the vehicle photo in its cell -- the same layout as the import sheet.\n// patch-vehicle-excel-redesign: the brand chosen in a list with its logo and how many models it has, a picture of the sheet's columns, and the\n// download in a bar (with what is being prepared, and the file name when it is done).\nconst mediaSrc = (url) => (url.startsWith(\"http\") ? url : `${API_BASE_URL}${url}`);\nconst COLUMNS = [[\"Brand\", true], [\"Model\", true], [\"Year\", false], [\"Version\", true], [\"Engine\", true], [\"Seats\", false], [\"Photo\", false]];\nconst SHEET_COLS = COLUMNS.reduce((n, [, three]) => n + (three ? 3 : 1), 0);\n\nexport default function VehicleExportPanel({ onSessionExpired }) {\n  const [brands, setBrands] = useState([]);\n  const [brandId, setBrandId] = useState(\"\");          // \"\" = all brands\n  const [busy, setBusy] = useState(false);\n  const [error, setError] = useState(null);\n  const [done, setDone] = useState(null);\n\n  useEffect(() => {\n    fetchBrands().then(setBrands).catch((err) => setError(err.message));\n  }, []);\n\n  const handleDownload = async () => {\n    setBusy(true); setError(null); setDone(null);\n    try {\n      const { blob, fileName } = await downloadVehicleExport(getStoredToken(), brandId || null);\n      const url = URL.createObjectURL(blob);\n      const link = document.createElement(\"a\");\n      link.href = url; link.download = fileName;\n      document.body.appendChild(link); link.click(); document.body.removeChild(link);\n      URL.revokeObjectURL(url);\n      setDone(fileName);\n    } catch (err) {\n      if (err instanceof SessionExpiredError) { onSessionExpired(); return; }\n      setError(err.message);\n    } finally {\n      setBusy(false);\n    }\n  };\n\n  const chosen = brands.find((b) => b.id === brandId) || null;\n  const totalModels = brands.reduce((n, b) => n + (Number(b.modelCount) || 0), 0);\n  const hasCounts = brands.some((b) => b.modelCount !== undefined);\n  const card = { border: `1px solid ${C.line}`, borderRadius: 14, background: \"#fff\", boxShadow: \"0 1px 2px rgba(11,49,70,0.05)\", marginBottom: 16, overflow: \"hidden\" };\n  const cell = { padding: \"7px 10px\", borderRight: \"1px solid #DDE5DF\", borderBottom: \"1px solid #DDE5DF\", whiteSpace: \"nowrap\" };\n  return (\n    <div data-testid=\"vehicle-export\">\n      <div style={card}>\n        <div style={{ display: \"flex\", gap: 14, alignItems: \"center\", padding: 18, flexWrap: \"wrap\" }}>\n          <div style={{ width: 46, height: 46, borderRadius: 12, background: \"#E7F4EC\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}><FileSpreadsheet size={22} color=\"#1D6F42\" /></div>\n          <div style={{ flex: \"1 1 380px\", minWidth: 0 }}>\n            <div style={{ ...disp, fontSize: 15.5, fontWeight: 800, color: C.ink }}>Download the vehicle data as an Excel sheet</div>\n            <div style={{ ...body, fontSize: 12.5, color: C.muted, marginTop: 3, lineHeight: 1.5 }}>\n              One row = one version of a vehicle in one year: brand, model, year, version, engine and seats in English, Arabic and Chinese, and the vehicle photo in its cell (click it to open it full size). All brands can take a minute because of the photos.\n            </div>\n          </div>\n        </div>\n\n        <div style={{ display: \"grid\", gridTemplateColumns: \"minmax(260px, 1fr) minmax(0, 1.6fr)\", gap: 18, padding: \"0 18px 18px\" }}>\n          {/* which brand */}\n          <div>\n            <label htmlFor=\"vehicle-export-brand\" style={{ ...body, display: \"block\", fontSize: 11.5, fontWeight: 800, color: C.muted, letterSpacing: \"0.06em\", textTransform: \"uppercase\", marginBottom: 6 }}>Brand</label>\n            <select id=\"vehicle-export-brand\" value={brandId} onChange={(e) => { setBrandId(e.target.value); setDone(null); }} disabled={busy}\n              style={{ ...body, width: \"100%\", height: 42, fontSize: 13.5, fontWeight: 700, padding: \"0 12px\", borderRadius: 10, border: `1px solid ${C.line}`, background: \"#fff\", color: C.ink }}>\n              <option value=\"\">All brands</option>\n              {brands.map((b) => <option key={b.id} value={b.id}>{b.name}{b.nameAr ? ` / ${b.nameAr}` : \"\"}</option>)}\n            </select>\n            <div style={{ display: \"flex\", alignItems: \"center\", gap: 12, marginTop: 12, padding: 12, borderRadius: 12, background: C.surfaceHigh, border: `1px solid ${C.line}` }}>\n              <div style={{ width: 48, height: 48, borderRadius: 12, background: \"#fff\", border: `1px solid ${C.line}`, overflow: \"hidden\", display: \"flex\", alignItems: \"center\", justifyContent: \"center\", flexShrink: 0 }}>\n                {chosen\n                  ? (chosen.photoUrl ? <img src={mediaSrc(chosen.photoUrl)} alt=\"\" style={{ width: \"100%\", height: \"100%\", objectFit: \"contain\" }} /> : <ImagePlus size={18} color={C.muted} />)\n                  : <span style={{ ...mono, fontSize: 15, fontWeight: 800, color: C.navy }}>{brands.length}</span>}\n              </div>\n              <div style={{ minWidth: 0 }}>\n                <div style={{ ...body, fontSize: 14, fontWeight: 800, color: C.ink }}>{chosen ? chosen.name : \"Every brand\"}</div>\n                <div style={{ ...body, fontSize: 12, color: C.muted }}>\n                  {chosen\n                    ? [chosen.nameAr, chosen.nameZh].filter(Boolean).join(\" · \") + (chosen.modelCount !== undefined ? `${chosen.nameAr || chosen.nameZh ? \" · \" : \"\"}${chosen.modelCount} ${chosen.modelCount === 1 ? \"model\" : \"models\"}` : \"\")\n                    : `${brands.length} ${brands.length === 1 ? \"brand\" : \"brands\"}${hasCounts ? ` · ${totalModels} ${totalModels === 1 ? \"model\" : \"models\"}` : \"\"} in one sheet`}\n                </div>\n              </div>\n            </div>\n          </div>\n\n          {/* what the sheet looks like */}\n          <div style={{ minWidth: 0 }}>\n            <div style={{ ...body, fontSize: 11.5, fontWeight: 800, color: C.muted, letterSpacing: \"0.06em\", textTransform: \"uppercase\", marginBottom: 6 }}>The sheet's columns</div>\n            <div style={{ border: \"1px solid #C9D8CE\", borderRadius: 10, overflow: \"hidden\" }}>\n              {/* a picture of the sheet (divs, not a table: the admin's table style would repaint it) */}\n              <div style={{ overflowX: \"auto\" }}>\n                <div style={{ display: \"grid\", gridTemplateColumns: `repeat(${SHEET_COLS}, minmax(52px, auto))`, ...body, fontSize: 11.5, minWidth: \"max-content\" }}>\n                  {COLUMNS.map(([name, three]) => <div key={name} style={{ ...cell, gridColumn: `span ${three ? 3 : 1}`, background: \"#1D6F42\", color: \"#fff\", borderColor: \"#2E8656\", fontWeight: 800 }}>{name}</div>)}\n                  {COLUMNS.flatMap(([name, three]) => (three ? [\"EN\", \"AR\", \"中文\"] : [\"\"]).map((l) => <div key={`${name}${l}`} style={{ ...cell, ...mono, background: \"#E7F4EC\", color: \"#1D6F42\", fontSize: 10, fontWeight: 800 }}>{l || \" \"}</div>))}\n                  {[\"Toyota\", \"تويوتا\", \"丰田\", \"Camry\", \"كامري\", \"凯美瑞\", \"2020\", \"GLE\", \"جي إل إي\", \"豪华版\", \"2.5L\", \"2.5 لتر\", \"2.5升\", \"5\"].map((v, i) => <div key={i} style={{ ...cell, color: C.muted, background: \"#fff\" }}>{v}</div>)}\n                  <div style={{ ...cell, background: \"#fff\" }}><span style={{ display: \"inline-flex\", width: 34, height: 20, borderRadius: 4, background: \"#DDE5DF\", alignItems: \"center\", justifyContent: \"center\" }}><ImagePlus size={11} color=\"#1D6F42\" /></span></div>\n                </div>\n              </div>\n            </div>\n            <div style={{ ...body, fontSize: 11.5, color: C.muted, marginTop: 6 }}>An example row. The same layout as the import template, so the file can be edited and imported again.</div>\n          </div>\n        </div>\n\n        {error && <div role=\"alert\" style={{ ...body, display: \"flex\", gap: 8, alignItems: \"center\", fontSize: 12.5, color: C.redInk, background: C.redBg, padding: \"10px 18px\" }}><AlertTriangle size={15} /> {error}</div>}\n        {done && <div role=\"status\" style={{ ...body, display: \"flex\", gap: 8, alignItems: \"center\", fontSize: 12.5, fontWeight: 700, color: \"#16794F\", background: \"#EEF8F3\", padding: \"10px 18px\" }}><Check size={15} /> Downloaded {done}</div>}\n\n        <div style={{ display: \"flex\", alignItems: \"center\", gap: 14, padding: \"14px 18px\", background: `linear-gradient(120deg, ${C.navyDeep}, ${C.navy} 60%, ${C.navySoft} 140%)`, flexWrap: \"wrap\" }}>\n          <span style={{ ...body, fontSize: 12.5, color: C.onNavyMuted, flex: \"1 1 260px\" }}>\n            {busy ? `Preparing ${chosen ? chosen.name : \"all brands\"} with the photos…` : chosen ? `${chosen.name} only, every model, year and version.` : \"All brands, every model, year and version.\"}\n          </span>\n          <button onClick={handleDownload} disabled={busy} style={{ ...body, display: \"inline-flex\", alignItems: \"center\", gap: 7, height: 42, padding: \"0 22px\", borderRadius: 10, border: `1px solid ${busy ? \"#D1D5DB\" : C.signalDark}`, background: busy ? \"#D1D5DB\" : C.signal, color: C.onSignal, fontSize: 14, fontWeight: 800, cursor: busy ? \"not-allowed\" : \"pointer\" }}>\n            <Download size={15} /> {busy ? \"Preparing the file…\" : \"Download Excel (.xlsx)\"}\n          </button>\n        </div>\n      </div>\n    </div>\n  );\n}\n"}], "anchored": []};
const fs = require('fs');
const path = require('path');
const root = path.join(__dirname, '..');
const write = process.argv.includes('--write');
const plan = [];
let problems = 0;
const once = (s, a) => s.split(a).length === 2;
const read = (file) => { const p = path.join(root, file); return fs.existsSync(p) ? fs.readFileSync(p, 'utf8') : null; };
function edit(file, what, done, change) {
  const s = read(file);
  if (s === null) { console.log(`MISSING   ${file}: not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; return; }
  if (s.replace(/\r\n/g, '\n').includes(done)) { console.log(`already   ${file}: ${what}`); return; }
  const eol = s.includes('\r\n') ? '\r\n' : '\n';
  const out = change(s.replace(/\r\n/g, '\n'));
  if (typeof out !== 'string') { console.log(`REFUSED   ${file}: ${out && out.why ? out.why : 'its text is not what this patch expects'}, so nothing was changed. Send this file.`); problems++; return; }
  plan.push({ file, what, before: s, after: out.replace(/\n/g, eol) });
}

for (const e of DATA.created) {
  const p = path.join(root, e.file);
  if (e.base64) {      // a picture: written as it is
    const bytes = Buffer.from(e.base64, 'base64');
    if (fs.existsSync(p)) {
      if (fs.readFileSync(p).equals(bytes)) { console.log(`already   ${e.file}: ${e.what}`); continue; }
      console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
    }
    if (!fs.existsSync(path.dirname(p))) { console.log(`MISSING   ${path.dirname(e.file)}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
    plan.push({ file: e.file, what: e.what, before: null, after: bytes });
    continue;
  }
  if (fs.existsSync(p)) {
    if (fs.readFileSync(p, 'utf8').replace(/\r\n/g, '\n') === e.text) { console.log(`already   ${e.file}: ${e.what}`); continue; }
    console.log(`REFUSED   ${e.file}: a different file with this name is already there, so nothing was changed. Send this file.`); problems++; continue;
  }
  // a new folder (services/api/src/modules/draftPhotos) is made, but only inside one that is already there
  if (!fs.existsSync(path.dirname(path.dirname(p)))) { console.log(`MISSING   ${path.dirname(path.dirname(e.file))}: folder not found. Run this from D:\\LEAP-MARKETPLACE.`); problems++; continue; }
  plan.push({ file: e.file, what: e.what, before: null, after: e.text });
}
for (const e of DATA.replaced || []) {
  edit(e.file, e.what, e.done, (s) => (e.from.includes(s) ? e.text : { why: 'it is not the version this patch expects' }));
}
for (const e of DATA.anchored) {
  // a test file: changed when it is there and as expected, otherwise left as it is (it does not stop the patch)
  if (e.optional) {
    const s = read(e.file);
    if (s === null) { console.log(`skipped   ${e.file}: not found (a test file; nothing to do)`); continue; }
    const n = s.replace(/\r\n/g, '\n');
    if (!n.includes(e.done) && (e.pairs.some(([a, , all]) => all !== 'maybe' && all !== 'alts' && !once(n, a)) || (e.block && (!n.includes(e.block.from) || !n.includes(e.block.to))))) { console.log(`skipped   ${e.file}: not as expected, left as it is (${e.what})`); continue; }
  }
  edit(e.file, e.what, e.done, (s) => {
    let out = s;
    for (const [a, b, all] of e.pairs) {
      if (all === 'alts') { const hit = a.find(([x]) => once(out, x)); if (!hit) return { why: `this part was not found: "${a[a.length - 1][0].split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.replace(hit[0], () => hit[1]); continue; }
      if (all === 'maybe') { if (once(out, a)) out = out.replace(a, () => b); continue; }
      if (all) { if (!out.includes(a)) return { why: `this part was not found: "${a.split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.split(a).join(b); continue; } if (!once(out, a)) return { why: `this part was not found: "${a.split('\n').find((l) => l.trim()).trim().slice(0, 90)}"` }; out = out.replace(a, () => b); }
    for (const [re, rep, min] of e.regex || []) { const r = new RegExp(re, 'g'); const n = (out.match(r) || []).length; if (n < min) return { why: `this part was not found: "${re.replace(/\\/g, '').slice(0, 70)}"` }; out = out.replace(r, rep); }
    if (e.region) {
      const r = e.region; const i = out.indexOf(r.from); const j = i < 0 ? -1 : out.indexOf(r.to, i);
      if (i < 0 || j < 0) return { why: `the part starting "${r.from.trim().slice(0, 60)}" was not found` };
      const seg = out.slice(i, j);
      if (r.must && !seg.includes(r.must)) return { why: `"${r.must}" was not found in the part starting "${r.from.trim().slice(0, 60)}"` };
      const changed = seg.replace(new RegExp(r.find, 'g'), r.repl);
      if (changed === seg) return { why: `nothing to change in the part starting "${r.from.trim().slice(0, 60)}"` };
      out = out.slice(0, i) + changed + out.slice(j);
    }
    if (e.block) {
      const i = out.indexOf(e.block.from); const j = i < 0 ? -1 : out.indexOf(e.block.to, i);
      if (i < 0 || j < 0) return { why: `the part starting "${e.block.from.trim().slice(0, 60)}" was not found` };
      out = out.slice(0, i) + e.block.text + out.slice(e.block.includeTo ? j + e.block.to.length : j);
    }
    return out;
  });
}
if (DATA.mount) edit('services/api/src/index.js', DATA.mount.what, DATA.mount.done, (s) => {
  const m = s.match(/\n([ \t]*)app\.use\('\/payouts', payoutsRoutes\);[^\n]*/);
  if (!m) return { why: "the line app.use('/payouts', payoutsRoutes); was not found" };
  const at = m.index + m[0].length;
  return s.slice(0, at) + `\n${m[1]}${DATA.mount.line}` + s.slice(at);
});
if (problems > 0) { console.log('\nNothing was changed, because of the problem(s) above.'); process.exit(1); }
for (const c of plan) {
  if (write) {
    const p = path.join(root, c.file);
    if (c.before !== null) fs.writeFileSync(`${p}.before-patch-vehicle-excel-redesign`, c.before);
    fs.mkdirSync(path.dirname(p), { recursive: true });
    fs.writeFileSync(p, c.after);
    console.log(`${c.before === null ? 'created ' : 'patched '}  ${c.file}: ${c.what}`);
  } else console.log(`would     ${c.file}: ${c.what}`);
}
if (!write && plan.length) console.log('\nDry run only. Add --write to apply.');
if (write && plan.length) console.log("\nDone. Refresh the admin with Ctrl+F5 (no API restart needed).");
